-- PREPARED -- NOT APPLIED.
--
-- FR: fill missing Google Place IDs, phone numbers and websites
-- (world contact-gap export of 2026-11-04). Generated by
-- world_contact_gaps/scripts/build_contact_fill_sql.py from the reviewed
-- research in fr_contact_fill.csv (evidence and the reason per row,
-- including every value held back).
--
-- Fill-only: a value is written only where the field is NULL; nothing is
-- overwritten. Place ID: the venue's own Google record (restaurant, or lodging
-- for a hotel), within 100 m of the stored point, or 100-500 m with the
-- official domain; never a hotel's record for a named restaurant inside it;
-- no search in mainland China. Phone: MICHELIN and Google agreeing, or the
-- number printed on the venue's own site; for a restaurant in a hotel only its
-- own page. Website: MICHELIN's link and the Google record agreeing on the
-- domain, or a site that loads and names the venue in its title or address;
-- never a booking, aggregator or social link; tracking parameters removed.
--
-- One transaction; any failed check rolls the whole file back. Safe to
-- re-run (fill-only).

begin;
-- restaurants: 6 rows (2 Place IDs, 2 phones, 5 websites)
create temp table _fill_restaurant (code text primary key, name text not null, place_id text unique, phone text, website text) on commit drop;
insert into _fill_restaurant values
    ('rest_0962', 'Frenchie', 'ChIJX8C6phdu5kcRA59bbRIGM5M', '+33 1 40 39 96 19', NULL),
    ('rest_1008', 'Le Tout-Paris', NULL, NULL, 'https://www.chevalblanc.com/fr/maison/paris/restaurants-et-bars/le-tout-paris/'),
    ('rest_1059', 'Guillaume Scheer - Les Plaisirs Gourmands', NULL, NULL, 'https://les-plaisirs-gourmands.com/'),
    ('rest_1091', 'Ivan Vautier', 'ChIJj9nmfx1DCkgRLyI9rCfAQxg', '+33 2 31 73 32 71', 'http://www.ivanvautier.com/'),
    ('rest_1101', 'Le Valucien - Château de Vault-de-Lugny', NULL, NULL, 'https://lugny.fr/'),
    ('rest_1208', 'Le 1862 - Les Glycines', NULL, NULL, 'https://www.les-glycines-dordogne.com/');

do $$
declare bad text;
begin
  -- identity: each code must still be the FR row of that name
  select string_agg(f.code, ', ') into bad from _fill_restaurant f
   where not exists (select 1 from public.restaurants x where x.restaurant_code = f.code and x.name = f.name and x.country_code = 'FR');
  if bad is not null then raise exception 'restaurants: code is no longer the exported FR row: %', bad; end if;
  -- Place IDs are unique per table
  select string_agg(f.code || ' -> ' || f.place_id || ' (held by ' || x.restaurant_code || ')', '; ') into bad
    from _fill_restaurant f join public.restaurants x on x.google_place_id = f.place_id and x.restaurant_code <> f.code;
  if bad is not null then raise exception 'restaurants: Place ID already used by another row: %', bad; end if;
end $$;

update public.restaurants x set google_place_id = f.place_id, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.place_id is not null and x.google_place_id is null;
update public.restaurants x set phone = f.phone, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.phone is not null and x.phone is null;
update public.restaurants x set website_url = f.website, updated_at = now()
  from _fill_restaurant f where x.restaurant_code = f.code and f.website is not null and x.website_url is null;

commit;
